require_once dirname(__DIR__).'/foundation/core.php';
function chr_ready(PDO $db):bool{try{return (bool)$db->query("SELECT name FROM hr_migrations WHERE name='005-core-hr'")->fetchColumn();}catch(Throwable $e){return false;}}
function chr_install(PDO $db):void{
 if(!foundation_ready($db))throw new InvalidArgumentException('Install Phase 1 first.');
 if(!$db->query("SELECT GET_LOCK('peopleflow_core_hr',10)")->fetchColumn())throw new RuntimeException('Installation in progress.');
 try{if(chr_ready($db))return;foreach(explode(';',file_get_contents(dirname(__DIR__,2).'/database/005-core-hr.sql')) as $sql)if(trim($sql)!=='')$db->exec($sql);
 foreach(['hr_attendance'=>'id,employee_id,attendance_date,check_in,check_out,shift_id,shift_snapshot,working_minutes,late_minutes,early_minutes,overtime_minutes,status,source,notes,version,updated_by,created_at,updated_at','hr_leave_details'=>'request_id,type_record_id,day_part,days,policy_snapshot,attachment_record_id','hr_leave_days'=>'request_id,leave_date,units,day_part'] as $table=>$columns)$db->query('SELECT '.$columns.' FROM '.$table.' LIMIT 0');
 $db->beginTransaction();foreach(['attendance'=>['view','manage','reports'],'leave'=>['view','create','approve','manage'],'holidays'=>['view','manage'],'shifts'=>['view','manage']] as $module=>$actions)foreach($actions as $action)$db->prepare('INSERT IGNORE INTO permissions(code,label) VALUES(?,?)')->execute([$module.'.'.$action,ucfirst($action).' '.$module]);$db->exec("INSERT INTO hr_migrations(name) VALUES('005-core-hr')");$db->commit();}catch(Throwable $e){if($db->inTransaction())$db->rollBack();throw $e;}finally{$db->query("SELECT RELEASE_LOCK('peopleflow_core_hr')");}
}
function chr_rows(PDO $db,string $module):array{$q=$db->prepare('SELECT * FROM hr_records WHERE module=? ORDER BY id DESC');$q->execute([$module]);$rows=$q->fetchAll(PDO::FETCH_ASSOC);foreach($rows as &$r)$r['values']=json_decode($r['data'],true)?:[];return $rows;}
function chr_record(PDO $db,string $module,int $id):?array{$q=$db->prepare('SELECT * FROM hr_records WHERE module=? AND id=?');$q->execute([$module,$id]);$r=$q->fetch(PDO::FETCH_ASSOC);if(!$r)return null;$r['values']=json_decode($r['data'],true)?:[];return $r;}
function chr_date(string $s):string{$d=fdate(['date'=>$s],'date');if(!$d)throw new InvalidArgumentException('Date is required.');return $d;}
function chr_number(array $in,string $key,float $max=1440):float{$s=$in[$key]??0;if(!is_numeric($s)||!is_finite((float)$s)||(float)$s<0||(float)$s>$max)throw new InvalidArgumentException('Check '.str_replace('_',' ',$key).'.');return (float)$s;}
function chr_time(array $in,string $key):string{$s=ftext($in,$key,5,true);if(!preg_match('/^(?:[01]\d|2[0-3]):[0-5]\d$/',$s))throw new InvalidArgumentException('Enter a valid time.');return $s;}
function chr_lock(PDO $db):void{$db->query("SELECT id FROM users WHERE role='super_admin' ORDER BY id LIMIT 1 FOR UPDATE")->fetchColumn();}
function chr_employee(PDO $db,int $id):array{$e=foundation_employee($db,$id);if(!$e)throw new InvalidArgumentException('Choose an existing employee.');return $e;}
function chr_shift_bounds(string $day,array $s):array{$start=new DateTimeImmutable($day.' '.$s['start']);$end=new DateTimeImmutable($day.' '.$s['end']);if($end<=$start)$end=$end->modify('+1 day');return [$start,$end];}
function chr_assignment(PDO $db,int $employee,string $day):?array{
 $employeeRow=chr_employee($db,$employee);return att_resolve(att_resolution_context($db),$employeeRow,$day);
}
function chr_holiday(PDO $db,string $day):?array{foreach(chr_rows($db,'holidays') as $r)if($r['status']==='Published'&&($r['values']['date']??'')===$day&&($r['values']['holiday_type']??'Company Holiday')!=='Optional Holiday')return $r;return null;}
function chr_weekoff(?array $shift,string $day):bool{return $shift&&in_array((int)date('N',strtotime($day)),array_map('intval',(array)($shift['values']['week_off']??[])),true);}
function chr_calculate(string $day,string $in,?string $out,?array $shift):array{
 $a=new DateTimeImmutable($in);$b=$out?new DateTimeImmutable($out):null;if($a->format('Y-m-d')!==$day)throw new InvalidArgumentException('Check-in must be on the attendance date.');if($b&&($b<=$a||$b->getTimestamp()-$a->getTimestamp()>36*3600))throw new InvalidArgumentException('Check-out must follow check-in, within 36 hours.');
 $result=['working_minutes'=>0,'late_minutes'=>0,'early_minutes'=>0,'overtime_minutes'=>0,'status'=>$b?'Present':'Open'];
 if($b)$result['working_minutes']=max(0,(int)floor(($b->getTimestamp()-$a->getTimestamp())/60)-(int)($shift['break_minutes']??0));
 if(!$shift)return $result;[$start,$end]=chr_shift_bounds($day,$shift);$late=max(0,(int)floor(($a->getTimestamp()-$start->getTimestamp())/60));$result['late_minutes']=$late>(int)($shift['grace']??0)?$late:0;
 if($b){$early=max(0,(int)floor(($end->getTimestamp()-$b->getTimestamp())/60));$result['early_minutes']=$early>(int)($shift['early_grace']??0)?$early:0;$after=max(0,(int)floor(($b->getTimestamp()-$end->getTimestamp())/60));$required=(int)round((float)($shift['required_hours']??$shift['overtime_after']??0)*60);$extra=$required>0?max(0,$result['working_minutes']-$required):0;$rule=$shift['overtime_rule']??'After required hours';$result['overtime_minutes']=$rule==='After shift end'?$after:($rule==='After both'?min($after,$extra):$extra);$half=(int)round((float)($shift['half_day_hours']??0)*60);$result['status']=$half>0&&$result['working_minutes']<$half?'Half Day':($result['late_minutes']>0?'Late':'Present');}
 if($b&&isset($shift['policy_id'])){$hours=$result['working_minutes']/60;$result['status']=$hours<max((float)($shift['minimum_hours']??0),(float)($shift['half_day_hours']??0))?'Absent':($hours<(float)$shift['required_hours']?'Half Day':($result['late_minutes']>0?'Late':'Present'));}
 return $result;
}
