 $perms=['shifts'=>'shifts.manage','roster'=>'shifts.manage','holidays'=>'holidays.manage','leave_policy'=>'leave.manage','balances'=>'leave.manage'];if(!isset($perms[$module])||!can($db,$actor,$perms[$module]))throw new InvalidArgumentException('You do not have permission to manage this section.');
 $db->beginTransaction();try{chr_lock($db);$id=(int)($in['id']??0);$old=$id?chr_record($db,$module,$id):null;if($id&&(!$old||(int)$old['version']!==(int)($in['version']??0)))throw new InvalidArgumentException('Record changed. Reload before saving.');$title=ftext($in,'title',190,true);$active=!empty($in['active']);$d=$old['values']??[];$owner=null;
 if($module==='shifts'){
 $d['code']=strtoupper(ftext($in,'code',40,true));foreach(chr_rows($db,$module) as $r)if((int)$r['id']!==$id&&strcasecmp($r['values']['code']??'',$d['code'])===0)throw new InvalidArgumentException('Shift code already exists.');$d['start']=chr_time($in,'start');$d['end']=chr_time($in,'end');if($d['start']===$d['end'])throw new InvalidArgumentException('Start and end cannot be identical.');foreach(['grace','early_grace','break_minutes'] as $k)$d[$k]=chr_number($in,$k);foreach(['required_hours','half_day_hours'] as $k)$d[$k]=chr_number($in,$k,24);if($d['required_hours']<=0||$d['half_day_hours']>$d['required_hours'])throw new InvalidArgumentException('Required hours must be positive and half-day threshold cannot exceed them.');[$a,$b]=chr_shift_bounds('2026-01-01',$d);if($d['break_minutes']>=($b->getTimestamp()-$a->getTimestamp())/60)throw new InvalidArgumentException('Break must be shorter than the shift.');$d['overtime_rule']=$in['overtime_rule']??'';if(!in_array($d['overtime_rule'],['After shift end','After required hours','After both'],true))throw new InvalidArgumentException('Select an overtime rule.');$d['overtime_after']=$d['required_hours'];$d['week_off']=array_values(array_unique(array_map('intval',(array)($in['week_off']??[]))));foreach($d['week_off'] as $n)if($n<1||$n>7)throw new InvalidArgumentException('Invalid week-off day.');$d['notes']=ftext($in,'notes',2000);
 }elseif($module==='roster'){
 $owner=(int)($in['employee_id']??0);chr_employee($db,$owner);$d['notes']=ftext($in,'notes',2000);$d['from']=chr_date((string)($in['from']??''));$d['to']=fdate($in,'to');if($d['to']&&$d['to']<$d['from'])throw new InvalidArgumentException('End date cannot precede start date.');$d['shift_id']=(int)($in['shift_id']??0);$shift=chr_record($db,'shifts',$d['shift_id']);if(!$shift||($shift['status']!=='Active'&&(!$old||(int)($old['values']['shift_id']??0)!==$d['shift_id'])))throw new InvalidArgumentException('Choose an active shift.');
 if($active)foreach(chr_rows($db,'roster') as $r){$v=$r['values'];if((int)$r['id']!==$id&&(int)$r['employee_id']===$owner&&$r['status']==='Active'&&($v['from']??'9999')<=($d['to']?:'9999-12-31')&&(($v['to']??null)?:'9999-12-31')>=$d['from'])throw new InvalidArgumentException('This assignment overlaps an existing assignment. End the old assignment before adding another.');}
 if($old&&($old['values']['from']??'9999')<=date('Y-m-d')&&((int)$old['employee_id']!==$owner||(int)$old['values']['shift_id']!==$d['shift_id']||$old['values']['from']!==$d['from']||!$active))throw new InvalidArgumentException('Preserve started assignments. Set their end date and create a new assignment.');
 if($old&&($old['values']['from']??'9999')<=date('Y-m-d')&&$d['to']&&$d['to']<date('Y-m-d')&&$d['to']!==($old['values']['to']??null))throw new InvalidArgumentException('An assignment end date cannot remove historical days. Use today or a later date.');
 $d['shift_snapshot']=$old&&isset($old['values']['shift_snapshot'])?$old['values']['shift_snapshot']:$shift['values'];if($old&&$old['values']['from']>date('Y-m-d'))$d['shift_snapshot']=$shift['values'];
 }elseif($module==='holidays'){
 $d['date']=chr_date((string)($in['date']??''));$d['description']=ftext($in,'description',2000);$d['holiday_type']=$in['holiday_type']??'';if(!in_array($d['holiday_type'],['Public Holiday','Company Holiday','Optional Holiday'],true))throw new InvalidArgumentException('Choose a holiday type.');if($active)foreach(chr_rows($db,'holidays') as $r)if((int)$r['id']!==$id&&$r['status']==='Published'&&($r['values']['date']??'')===$d['date'])throw new InvalidArgumentException('An active holiday already exists on this date.');
 }elseif($module==='leave_policy'){
