 }else{
 $owner=(int)($in['employee_id']??0);chr_employee($db,$owner);if($old&&(int)$old['employee_id']!==$owner)throw new InvalidArgumentException('The entitlement employee cannot be changed.');$year=(int)chr_number($in,'year',2200);if($year<2000)throw new InvalidArgumentException('Enter a year from 2000 to 2200.');if($old&&(int)($old['values']['year']??0)!==$year)throw new InvalidArgumentException('The entitlement year cannot be changed.');$type=ftext($in,'type',40,true);$policy=chr_policy($db,$type);if(!$policy)throw new InvalidArgumentException('Choose a leave type.');$allocation=chr_number($in,'allocation',366);$carry=chr_number($in,'carry',366);if($carry>(float)($policy['values']['carry_forward']??0))throw new InvalidArgumentException('Carry-forward exceeds the configured cap.');if($active&&!($policy['values']['allow_negative']??false)&&$allocation+$carry<chr_used($db,$owner,$type,$year))throw new InvalidArgumentException('Allocation cannot be lower than already approved usage.');$d['year']=$year;$d[$type]=$allocation+$carry;$d['allocation_details'][$type]=['allocated'=>$allocation,'carry'=>$carry];$d['notes']=ftext($in,'notes',2000);foreach(chr_rows($db,'balances') as $r)if((int)$r['id']!==$id&&(int)$r['employee_id']===$owner&&(int)($r['values']['year']??0)===$year&&$r['status']==='Active')throw new InvalidArgumentException('An entitlement record already exists for this employee and year. Edit it to add or change a type.');
 }
 $status=$active?(in_array($module,['holidays','leave_policy'],true)?'Published':'Active'):($module==='roster'?'Cancelled':(in_array($module,['holidays','leave_policy'],true)?'Draft':'Inactive'));
 if($old&&$module==='shifts')foreach(chr_rows($db,'roster') as $assignment){$values=$assignment['values'];if((int)($values['shift_id']??0)===$id&&!isset($values['shift_snapshot'])){$values['shift_snapshot']=$old['values'];$db->prepare('UPDATE hr_records SET data=?,version=version+1 WHERE id=?')->execute([json_encode($values),$assignment['id']]);}}
 if($old)$db->prepare('UPDATE hr_records SET title=?,status=?,employee_id=?,data=?,version=version+1 WHERE id=?')->execute([$title,$status,$owner,json_encode($d),$id]);else{$db->prepare('INSERT INTO hr_records(module,employee_id,title,status,data,created_by) VALUES(?,?,?,?,?,?)')->execute([$module,$owner,$title,$status,json_encode($d),$actor['id']]);$id=(int)$db->lastInsertId();}faudit($db,$actor,'core.'.$module.'.saved',$id);$db->commit();return $id;
 }catch(Throwable $e){if($db->inTransaction())$db->rollBack();throw $e;}
}
function chr_delete_config(PDO $db,array $actor,string $module,int $id):void{
 $p=['shifts'=>'shifts.manage','holidays'=>'holidays.manage'];if(!isset($p[$module])||!can($db,$actor,$p[$module]))throw new InvalidArgumentException('Delete is not permitted.');$db->beginTransaction();try{chr_lock($db);$r=chr_record($db,$module,$id);if(!$r)throw new InvalidArgumentException('Record not found.');if($module==='shifts')foreach(array_merge(chr_rows($db,'roster'),chr_rows($db,'shift_defaults'),chr_rows($db,'time_policies')) as $a)if((int)($a['values']['shift_id']??0)===$id)throw new InvalidArgumentException('This shift has assignment history. Deactivate it instead.');if($module==='holidays'&&($r['values']['date']??'')<=date('Y-m-d'))throw new InvalidArgumentException('Preserve past holidays; deactivate only if correcting an error.');$db->prepare('DELETE FROM hr_records WHERE id=? AND module=?')->execute([$id,$module]);faudit($db,$actor,'core.'.$module.'.deleted',$id);$db->commit();}catch(Throwable $e){if($db->inTransaction())$db->rollBack();throw $e;}}
